with target as(select * from public.works where id=any(array[3544,4951,4953,4966,4975,4982,4990,5745,5794,5820]::bigint[]) or open_library_id=any(array['OL3000715W','OL79320W','OL37569957W','OL24317185W','OL1914089W','OL17792623W','OL4279476W','OL19648W','OL276301W','OL17800879W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['fromheretoeternity','schijnbeweging','onefalsemove','dedixonregels','thedixonrule','hetmooisdatwedelen','opvleugelsvandeadelaar','onwingsofeagles','tijgerklauwswoede','tigerclawsfury','nadestorm','paradisevalley','devilla','thecottage','museumvanonvoorwaardelijkeovergave','muzejbezuvjetnepredaje','opditmoment','inthismoment']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['fromheretoeternity','schijnbeweging','onefalsemove','dedixonregels','thedixonrule','hetmooisdatwedelen','opvleugelsvandeadelaar','onwingsofeagles','tijgerklauwswoede','tigerclawsfury','nadestorm','paradisevalley','devilla','thecottage','museumvanonvoorwaardelijkeovergave','muzejbezuvjetnepredaje','opditmoment','inthismoment']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL889275A','OL39821A','OL6761347A','OL9145941A','OL229268A','OL1389873A','OL829823A','OL24452A','OL185745A','OL32066A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['jamesjones','harlancoben','cobenharlan','ellekennedy','ellekennedyauteurderomanssentimentaux','ellekennedycanadianwriter','ishaithamou','kenfollett','follettken','follettkennethmartin','kennethmfollett','erinhunter','katecarycherithbaldrytuisutherlandandvictoriaholmes','erinwhunterebook','erinlhunter','robyncarr','robynlcarr','daniellesteel','dubravkaugresic','karenkingsbury']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL60810198M','OL33221576M','OL60492058M','OL32177800M','OL32946529M','OL42322636M','OL60553133M','OL12800494M','OL47319722M','OL42518928M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789045208565','9789022552070','9789021499239','9789022336953','9789026978692','9789059246232','9789402714128','9789024549320','9789038811574','9789043531191']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
